interface GitHubApi {
    @GET("users/{user}/repos")
    suspend fun repos(
        @Path("user") user: String,
        @Query("sort") sort: String = "updated",
        @Query("per_page") perPage: Int = 30,
    ): List<RepoDto>

    @GET("repos/{owner}/{repo}")
    suspend fun repo(@Path("owner") owner: String, @Path("repo") repo: String): Response<RepoDto>
}

val api: GitHubApi = Retrofit.Builder()
    .baseUrl("https://api.github.com/")
    .addConverterFactory(Json { ignoreUnknownKeys = true }.asConverterFactory("application/json".toMediaType()))
    .build()
    .create()

class RepoRepositoryTest {
    private val server = MockWebServer()
    private lateinit var repo: RepoRepository

    @Before fun setUp() {
        server.start()
        val api = Retrofit.Builder()
            .baseUrl(server.url("/"))
            .addConverterFactory(Json { ignoreUnknownKeys = true }.asConverterFactory("application/json".toMediaType()))
            .build().create<GitHubApi>()
        repo = RepoRepository(api)
    }
    @After fun tearDown() = server.shutdown()

    @Test fun mapsReposAndSendsTheRightQuery() = runTest {
        server.enqueue(MockResponse().setBody("""[{"id":1,"name":"devpath","stargazers_count":42,"owner":{"login":"x"}}]"""))

        val repos = repo.repos("octocat")

        assertEquals(listOf(Repo(id = 1, name = "devpath", stars = 42, description = "")), repos)
        val request = server.takeRequest()
        assertEquals("/users/octocat/repos?sort=updated&per_page=30", request.path)
    }
}

class OfflineCacheInterceptor(private val isOnline: () -> Boolean) : Interceptor {
    override fun intercept(chain: Interceptor.Chain): Response {
        var request = chain.request()
        if (!isOnline()) {
            request = request.newBuilder()
                .cacheControl(CacheControl.Builder().onlyIfCached().maxStale(7, TimeUnit.DAYS).build())
                .build()
        }
        return chain.proceed(request)              // 504 if nothing is cached
    }
}

