@Serializable data class ApiErrorBody(val field: String? = null, val message: String)

private val errorJson = Json { ignoreUnknownKeys = true }

fun String?.toValidation(): NetworkError =
    this?.let { runCatching { errorJson.decodeFromString<ApiErrorBody>(it) }.getOrNull() }
        ?.let { NetworkError.Validation(it.field, it.message) }
        ?: NetworkError.Server(422)

