fun Context.connectivity(): Flow<Boolean> = callbackFlow {
    val cm = getSystemService(ConnectivityManager::class.java)
    val callback = object : ConnectivityManager.NetworkCallback() {
        override fun onAvailable(network: Network) { trySend(true) }
        override fun onLost(network: Network) { trySend(false) }
    }
    trySend(cm.activeNetwork != null)
    cm.registerDefaultNetworkCallback(callback)
    awaitClose { cm.unregisterNetworkCallback(callback) }
}.distinctUntilChanged()

@Composable
fun NetworkError.message(): String = when (this) {
    NetworkError.NoConnection -> stringResource(R.string.error_offline)
    NetworkError.Timeout -> stringResource(R.string.error_slow)
    NetworkError.Unauthorized -> stringResource(R.string.error_signed_out)
    NetworkError.NotFound -> stringResource(R.string.error_not_found)
    is NetworkError.Validation -> message
    is NetworkError.Server, is NetworkError.Unexpected -> stringResource(R.string.error_generic)
}

interface TokenStore {
    suspend fun accessToken(): String?
    suspend fun refreshToken(): String?
    suspend fun save(access: String, refresh: String)
    suspend fun clear()
}

@Module @InstallIn(SingletonComponent::class)
object NetworkModule {
    @Provides @Singleton @Named("auth")
    fun authClient(): OkHttpClient = OkHttpClient.Builder().build()            // no authenticator here

    @Provides @Singleton
    fun apiClient(tokens: TokenStore, authenticator: TokenAuthenticator): OkHttpClient =
        OkHttpClient.Builder()
            .addInterceptor(AuthInterceptor(tokens))
            .authenticator(authenticator)
            .build()
}

