class EncryptedTokenStore(
    private val store: DataStore<Preferences>,
    private val aead: Aead,                          // Tink AEAD backed by an Android Keystore master key
) : TokenStore {
    private val ACCESS = stringPreferencesKey("a")
    private val REFRESH = stringPreferencesKey("r")

    private fun enc(v: String) = Base64.encodeToString(aead.encrypt(v.encodeToByteArray(), null), Base64.NO_WRAP)
    private fun dec(v: String) = aead.decrypt(Base64.decode(v, Base64.NO_WRAP), null).decodeToString()

    override suspend fun accessToken() = store.data.first()[ACCESS]?.let(::dec)
    override suspend fun refreshToken() = store.data.first()[REFRESH]?.let(::dec)
    override suspend fun save(access: String, refresh: String) {
        store.edit { it[ACCESS] = enc(access); it[REFRESH] = enc(refresh) }
    }
    override suspend fun clear() { store.edit { it.clear() } }
}

