class SearchPagingSource(private val api: SearchApi, private val query: String) : PagingSource<Int, ResultDto>() {
    override suspend fun load(params: LoadParams<Int>): LoadResult<Int, ResultDto> = try {
        val page = params.key ?: 1
        val response = api.search(query, page = page, size = params.loadSize)
        LoadResult.Page(
            data = response.items,
            prevKey = if (page == 1) null else page - 1,
            nextKey = if (response.items.isEmpty()) null else page + 1,
        )
    } catch (e: IOException) {
        LoadResult.Error(e)
    } catch (e: HttpException) {
        LoadResult.Error(e)
    }

    override fun getRefreshKey(state: PagingState<Int, ResultDto>): Int? =
        state.anchorPosition?.let { state.closestPageToPosition(it)?.prevKey?.plus(1) }
}

@Composable
fun SearchResults(items: LazyPagingItems<SearchResult>) {
    when (val s = items.loadState.refresh) {
        is LoadState.Loading -> FullScreenSpinner()
        is LoadState.Error -> ErrorScreen(onRetry = items::retry)
        else -> LazyColumn {
            items(items.itemCount, key = items.itemKey { it.id }) { i -> items[i]?.let { ResultRow(it) } }
            if (items.loadState.append is LoadState.Loading) item { LoadingRow() }
        }
    }
}

@Entity(tableName = "remote_keys")
data class RemoteKey(@PrimaryKey val feed: String, val nextCursor: String?, val updatedAt: Long)

@OptIn(ExperimentalPagingApi::class)
class FeedMediator(
    private val db: AppDatabase,
    private val api: FeedApi,
    private val clock: Clock,
) : RemoteMediator<Int, PostEntity>() {

    override suspend fun initialize(): InitializeAction {
        val updated = db.remoteKeys().get("home")?.updatedAt ?: 0
        return if (clock.millis() - updated < 30.minutes.inWholeMilliseconds) InitializeAction.SKIP_INITIAL_REFRESH
        else InitializeAction.LAUNCH_INITIAL_REFRESH
    }

    override suspend fun load(loadType: LoadType, state: PagingState<Int, PostEntity>): MediatorResult {
        val cursor = when (loadType) {
            LoadType.REFRESH -> null
            LoadType.PREPEND -> return MediatorResult.Success(endOfPaginationReached = true)
            LoadType.APPEND -> db.remoteKeys().get("home")?.nextCursor
                ?: return MediatorResult.Success(endOfPaginationReached = true)
        }
        return try {
            val page = api.feed(cursor, state.config.pageSize)
            db.withTransaction {
                if (loadType == LoadType.REFRESH) { db.posts().clearFeed("home"); db.remoteKeys().delete("home") }
                db.remoteKeys().upsert(RemoteKey("home", page.nextCursor, clock.millis()))
                db.posts().upsertAll(page.items.map { it.toEntity(feed = "home") })
            }
            MediatorResult.Success(endOfPaginationReached = page.nextCursor == null)
        } catch (e: IOException) { MediatorResult.Error(e) } catch (e: HttpException) { MediatorResult.Error(e) }
    }
}

