class LiveScoreViewModel(private val repo: ScoreRepository, matchId: String) : ViewModel() {
    val score: StateFlow<ScoreUi> = repo.liveScore(matchId)
        .map { it.toUi() }
        .catch { emit(ScoreUi.Unavailable) }
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), ScoreUi.Loading)
}

class ScoreRepository(private val client: OkHttpClient) {
    fun liveScore(matchId: String): Flow<ScoreEvent> =
        client.events("wss://live.example.com/matches/$matchId")
            .retryWhen { cause, attempt ->
                val retryable = cause is IOException
                if (retryable) delay(minOf(30_000L, 1_000L * (1L shl attempt.toInt().coerceAtMost(5))))
                retryable
            }
}

