class AppMessagingService : FirebaseMessagingService() {
    override fun onNewToken(token: String) {
        PushTokenWorker.enqueue(applicationContext, token)          // send to your server
    }

    override fun onMessageReceived(message: RemoteMessage) {
        when (message.data["type"]) {
            "chat" -> ChatSyncWorker.enqueue(applicationContext, conversationId = message.data["cid"])
            "order" -> OrderSyncWorker.enqueue(applicationContext)
        }
    }
}

class ChatRepository(private val dao: MessageDao, private val api: ChatApi) {
    suspend fun resync(conversationId: String) {
        val after = dao.lastSequence(conversationId) ?: 0L
        val missed = api.messages(conversationId, afterSequence = after)
        dao.upsertAll(missed.map { it.toEntity() })                   // ids are primary keys: no duplicates
    }
}
